df_base = load_data()

COLOR_MAP = {
    "PBA CENTRO-SUR":"#2E75B6","COSTA ATLANTICA":"#1D9E75","COSTA ATLÁNTICA":"#1D9E75",
    "LITORAL":"#3B6D11","MISIONES":"#BA7517","NEA":"#D85A30","GBA":"#534AB7","BS. AS.":"#993556",
    "COMAHUE":"#1A7BAF","PATAGONIA":"#0D4C73","NOA":"#C84B11","CENTRO":"#5C8A1E","CUYO":"#8B1A8B",
}

# === HEADER ===
st.markdown("# 🔮 AURA Energy - Prospeccion de oportunidades futuras")
st.markdown("Simula la **ampliacion de los corredores de exportacion** (limite 6) y descubri que nodos de buena radiacion se liberarian. Herramienta de posicionamiento anticipado.")
st.markdown("---")

# === SIDEBAR: inputs de L6 futuro ===
with st.sidebar:
    st.markdown("## 🔮 Escenario futuro")
    st.markdown("**Editá el límite 6 de cada corredor**")
    st.caption("El valor actual es el real de Cammesa 2T2026. Cambiá el futuro para simular ampliaciones de red.")
    st.markdown("---")

    l6_futuro = {}
    for grupo, actual in GRUPOS_L6_ACTUAL.items():
        st.markdown(f"**{grupo}**")
        st.caption(f"Actual: {actual} MW")
        l6_futuro[grupo] = st.number_input(
            f"Futuro {grupo} (MW)", min_value=0, max_value=3000, value=int(actual), step=10,
            key=f"l6_{grupo}", label_visibility="collapsed",
        )
        st.markdown("")

    st.markdown("---")
    st.markdown("### Pesos del ranking")
    w_ghi = st.slider("Peso GHI (recurso solar)", 0, 100, 90, 5,
                      help="En prospeccion el recurso pesa mas: buscamos nodos de alta radiacion.")
    w_mw = 100 - w_ghi
    st.markdown(f"Peso MW: **{w_mw}%**")

    st.markdown("---")
    solo_despiertan = st.toggle("Ver solo nodos que despiertan", value=False,
                                help="Muestra unicamente los nodos cuya capacidad aumenta respecto al escenario actual.")

# === RECALCULO con L6 futuro ===
def recalcular(row):
    grupo = row["grupo"]
    if grupo in l6_futuro:
        l6 = l6_futuro[grupo]
        return min(row["min_sin_l6"], l6)
    return row["min_sin_l6"]  # sin grupo: fijo

df = df_base.copy()
df["cap_futuro"] = df.apply(recalcular, axis=1)
df["delta"] = df["cap_futuro"] - df["cap_actual"]
df = df[df["cap_futuro"] > 0].copy()

# Ranking sobre cap futuro
if not df.empty:
    gn = (df.ghi - df.ghi.min()) / (df.ghi.max() - df.ghi.min()) if df.ghi.max()!=df.ghi.min() else 1.0
    mn = (df.cap_futuro - df.cap_futuro.min()) / (df.cap_futuro.max() - df.cap_futuro.min()) if df.cap_futuro.max()!=df.cap_futuro.min() else 1.0
    df["score"] = (w_ghi/100)*gn + (w_mw/100)*mn
    df["rk"] = df["score"].rank(ascending=False, method="min").astype(int)

if solo_despiertan:
    df_f = df[df["delta"] > 0].copy()
else:
    df_f = df.copy()

# === METRICAS ===
total_actual = int(df_base["cap_actual"].sum())
total_futuro = int(df["cap_futuro"].sum())
mw_liberados = total_futuro - total_actual
nodos_despiertan = (df["delta"] > 0).sum()

m1,m2,m3,m4 = st.columns(4)
with m1: st.markdown(f'<div class="metric-card"><div class="metric-lbl">MW actuales</div><div class="metric-val">{total_actual:,}</div></div>', unsafe_allow_html=True)
with m2: st.markdown(f'<div class="metric-card"><div class="metric-lbl">MW escenario futuro</div><div class="metric-val">{total_futuro:,}</div></div>', unsafe_allow_html=True)
with m3: st.markdown(f'<div class="metric-card"><div class="metric-lbl" style="color:#6A5ACD">MW que se liberan</div><div class="metric-val" style="color:#6A5ACD">+{mw_liberados:,}</div></div>', unsafe_allow_html=True)
with m4: st.markdown(f'<div class="metric-card"><div class="metric-lbl">Nodos que despiertan</div><div class="metric-val">{nodos_despiertan}</div></div>', unsafe_allow_html=True)
st.markdown("---")

tab1, tab2, tab3 = st.tabs(["🏆 Nodos que se liberan", "🗺️ Mapa", "📋 Tabla completa"])

with tab1:
    st.markdown("### Nodos ordenados por potencial (ranking futuro)")
    st.caption("Prioridad al recurso solar (GHI). El delta muestra cuantos MW gana cada nodo con la ampliacion simulada.")
    df_show = df_f.sort_values("rk").head(40)
    if df_show.empty:
        st.info("Ajusta los valores de L6 en el panel izquierdo para ver nodos.")
    else:
        for _, r in df_show.iterrows():
            cc = COLOR_MAP.get(r.corredor, "#888")
            delta_badge = f'<span style="background:#E7E0FF;color:#3C3489;padding:1px 8px;border-radius:10px;font-size:.75rem;font-weight:600">+{int(r.delta)} MW</span>' if r.delta > 0 else ''
            st.markdown(f'<div style="border-left:3px solid {cc};padding:6px 10px;margin:3px 0;background:#FAFAFA;border-radius:0 6px 6px 0"><span style="font-weight:600;color:#3C3489">#{int(r["rk"])} {r["nombre"]}</span> <span style="font-size:.78rem;color:#888">{r.corredor}</span> {delta_badge}<br><span style="font-size:.82rem">GHI <b>{r.ghi}</b> - actual <b>{int(r.cap_actual)} MW</b> → futuro <b>{int(r.cap_futuro)} MW</b> - score {r.score:.3f}</span></div>', unsafe_allow_html=True)

with tab2:
    df_map = df_f.dropna(subset=["lat","lon"]).copy()
    st.markdown(f"### Mapa ({len(df_map)} nodos con coordenadas)")
    st.caption("Tamano = capacidad futura simulada - Color = corredor")
    if df_map.empty:
        st.info("Sin nodos con coordenadas para este escenario.")
    else:
        fig = px.scatter_mapbox(df_map, lat="lat", lon="lon", color="corredor", size="cap_futuro", size_max=30,
            color_discrete_map=COLOR_MAP, hover_name="nombre",
            hover_data={"id":True,"ghi":True,"cap_actual":True,"cap_futuro":True,"delta":True,"lat":False,"lon":False},
            zoom=3.7, center={"lat":-34,"lon":-64}, mapbox_style="open-street-map")
        fig.update_layout(height=560, margin={"r":0,"t":0,"l":0,"b":0},
            legend=dict(orientation="v", x=0.01, y=0.99, bgcolor="rgba(255,255,255,0.85)"))
        st.plotly_chart(fig, use_container_width=True)

with tab3:
    st.markdown("### Tabla completa - escenario simulado")
    cols = ["rk","nombre","corredor","grupo","ghi","cap_actual","cap_futuro","delta","score","id"]
    ds = df_f[cols].sort_values("rk").copy()
    ds.columns = ["Rk","Nombre","Corredor","Grupo export.","GHI","Cap. actual","Cap. futura","Delta","Score","ID"]
    st.dataframe(ds, use_container_width=True, height=500, hide_index=True, column_config={
        "Rk": st.column_config.NumberColumn(format="%d"),
        "GHI": st.column_config.NumberColumn(format="%d"),
        "Cap. actual": st.column_config.NumberColumn(format="%d MW"),
        "Cap. futura": st.column_config.NumberColumn(format="%d MW"),
        "Delta": st.column_config.NumberColumn(format="+%d MW"),
        "Score": st.column_config.NumberColumn(format="%.3f")})

st.markdown("---")
st.caption("AURA Energy - Prospeccion futura sobre MATER Solar 2T2026 - Los valores futuros son simulaciones de ampliacion de red, NO capacidad real disponible hoy - GHI: Global Solar Atlas")
